typedef long long ll;

typedef struct {
    int t;
    int p;
} Event;

int cmpEvent(const void *a, const void *b) {
    const Event *x = (const Event *)a;
    const Event *y = (const Event *)b;
    if (x->t != y->t) return x->t - y->t;
    return x->p - y->p;
}

typedef struct {
    int score;
    int id;
} HeapNode;

/* Max-heap by score, and for ties smaller id is better */
int better(HeapNode a, HeapNode b) {
    if (a.score != b.score) return a.score > b.score;
    return a.id < b.id;
}

void heap_swap(HeapNode *a, HeapNode *b) {
    HeapNode t = *a;
    *a = *b;
    *b = t;
}

void heap_up(HeapNode *heap, int idx) {
    while (idx > 1) {
        int p = idx / 2;
        if (better(heap[p], heap[idx])) break;
        heap_swap(&heap[p], &heap[idx]);
        idx = p;
    }
}

void heap_down(HeapNode *heap, int sz, int idx) {
    while (1) {
        int l = idx * 2;
        int r = l + 1;
        int best = idx;
        if (l <= sz && better(heap[l], heap[best])) best = l;
        if (r <= sz && better(heap[r], heap[best])) best = r;
        if (best == idx) break;
        heap_swap(&heap[idx], &heap[best]);
        idx = best;
    }
}

void heap_push(HeapNode *heap, int *sz, HeapNode x) {
    heap[++(*sz)] = x;
    heap_up(heap, *sz);
}

HeapNode heap_top(HeapNode *heap) {
    return heap[1];
}

void heap_pop(HeapNode *heap, int *sz) {
    heap[1] = heap[*sz];
    (*sz)--;
    if (*sz > 0) heap_down(heap, *sz, 1);
}

int main(void) {
    int n, m, L;
    if (scanf("%d %d %d", &n, &m, &L) != 3) return 0;

    Event *events = (Event *)malloc(sizeof(Event) * m);
    for (int i = 0; i < m; i++) {
        scanf("%d %d", &events[i].t, &events[i].p);
    }

    qsort(events, m, sizeof(Event), cmpEvent);

    int *score = (int *)calloc(n + 1, sizeof(int));
    ll *tv = (ll *)calloc(n + 1, sizeof(ll));

    /* Lazy heap: push new (score,id) whenever score changes */
    HeapNode *heap = (HeapNode *)malloc(sizeof(HeapNode) * (n + m + 5));
    int hsz = 0;

    for (int i = 1; i <= n; i++) {
        heap_push(heap, &hsz, (HeapNode){0, i});
    }

    int curTime = 0;
    int idx = 0;

    while (idx < m) {
        while (hsz > 0) {
            HeapNode top = heap_top(heap);
            if (score[top.id] == top.score) break;
            heap_pop(heap, &hsz);
        }

        int leader = heap_top(heap).id;
        int t = events[idx].t;
        tv[leader] += (ll)(t - curTime);

        while (idx < m && events[idx].t == t) {
            int team = events[idx].p;
            score[team]++;
            heap_push(heap, &hsz, (HeapNode){score[team], team});
            idx++;
        }

        curTime = t;
    }

    while (hsz > 0) {
        HeapNode top = heap_top(heap);
        if (score[top.id] == top.score) break;
        heap_pop(heap, &hsz);
    }

    int leader = heap_top(heap).id;
    tv[leader] += (ll)(L - curTime);

    int ans = 1;
    for (int i = 2; i <= n; i++) {
        if (tv[i] > tv[ans]) ans = i;
    }

    printf("%d\n", ans);

    free(events);
    free(score);
    free(tv);
    free(heap);
    return 0;
}

