public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int L = sc.nextInt();
        int N = sc.nextInt();

        // TreeMap to store times when score changes occur, for each team
        Map<Integer, TreeMap<Integer, Integer>> teamScores = new HashMap<>();

        for (int i = 0; i < N; i++) {
            int t = sc.nextInt();
            int team = sc.nextInt();
            int scoreChange = sc.nextInt();
            teamScores.putIfAbsent(team, new TreeMap<>());
            TreeMap<Integer, Integer> changes = teamScores.get(team);
            changes.put(t, changes.getOrDefault(changes.lastKey(), 0) + scoreChange);
        }

        // Merge all events into a timeline
        TreeMap<Integer, List<int[]>> events = new TreeMap<>(); // time -> list of (team, newScore)

        for (int team : teamScores.keySet()) {
            TreeMap<Integer, Integer> changes = teamScores.get(team);
            int currentScore = 0;
            for (int time : changes.keySet()) {
                currentScore += changes.get(time);
                events.putIfAbsent(time, new ArrayList<>());
                events.get(time).add(new int[]{team, currentScore});
            }
        }

        // Simulate the contest
        int currentTime = 0;
        int bestTeam = -1;
        int bestScore = -1;
        Map<Integer, Integer> scoreMap = new HashMap<>();
        Map<Integer, Long> tvTime = new HashMap<>();

        // Add initial state at time 0
        events.putIfAbsent(0, new ArrayList<>());
        for (int team : teamScores.keySet()) {
            scoreMap.put(team, 0);
        }

        // Determine initial leader (smallest ID among score 0)
        bestTeam = Integer.MAX_VALUE;
        for (int team : scoreMap.keySet()) {
            if (team < bestTeam) {
                bestTeam = team;
            }
        }
        bestScore = 0;

        for (int time : events.keySet()) {
            // Time interval from currentTime to time-1 with current leader
            if (currentTime < time) {
                long duration = time - currentTime;
                tvTime.put(bestTeam, tvTime.getOrDefault(bestTeam, 0L) + duration);
            }

            // Apply events at this time
            for (int[] event : events.get(time)) {
                int team = event[0];
                int newScore = event[1];
                scoreMap.put(team, newScore);
            }

            // Determine new leader
            int newBestTeam = -1;
            int newBestScore = Integer.MIN_VALUE;
            for (int team : scoreMap.keySet()) {
                int scTeam = scoreMap.get(team);
                if (scTeam > newBestScore || (scTeam == newBestScore && team < newBestTeam)) {
                    newBestScore = scTeam;
                    newBestTeam = team;
                }
            }

            bestTeam = newBestTeam;
            bestScore = newBestScore;
            currentTime = time;
        }

        // Remaining time from last event to L
        if (currentTime < L) {
            long duration = L - currentTime;
            tvTime.put(bestTeam, tvTime.getOrDefault(bestTeam, 0L) + duration);
        }

        // Find team with maximum TV time
        long maxTime = -1;
        int resultTeam = -1;
        for (int team : tvTime.keySet()) {
            long timeOnTV = tvTime.get(team);
            if (timeOnTV > maxTime) {
                maxTime = timeOnTV;
                resultTeam = team;
            } else if (timeOnTV == maxTime && team < resultTeam) {
                resultTeam = team;
            }
        }

        System.out.println(resultTeam);
    }
}

