public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Team implements Comparable<Team> {
        int id;
        int score;

        Team(int id, int score) {
            this.id = id;
            this.score = score;
        }

        @Override
        public int compareTo(Team other) {
            if (this.score != other.score) return Integer.compare(other.score, this.score); // higher score first
            return Integer.compare(this.id, other.id); // smaller id first
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Team)) return false;
            Team t = (Team) o;
            return id == t.id && score == t.score;
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, score);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();   // number of teams
        int m = fs.nextInt();   // number of log entries
        int L = fs.nextInt();   // contest length

        int[] score = new int[n + 1];
        long[] shown = new long[n + 1];

        TreeSet<Team> set = new TreeSet<>();
        for (int i = 1; i <= n; i++) {
            set.add(new Team(i, 0));
        }

        int prevTime = 0;

        for (int i = 0; i < m; i++) {
            int t = fs.nextInt();
            int teamId = fs.nextInt();
            int delta = fs.nextInt();

            Team leader = set.first();
            shown[leader.id] += (long) t - prevTime;

            Team oldTeam = new Team(teamId, score[teamId]);
            set.remove(oldTeam);

            score[teamId] += delta;
            Team newTeam = new Team(teamId, score[teamId]);
            set.add(newTeam);

            prevTime = t;
        }

        Team leader = set.first();
        shown[leader.id] += (long) L - prevTime;

        int answer = 1;
        for (int i = 2; i <= n; i++) {
            if (shown[i] > shown[answer] || (shown[i] == shown[answer] && i < answer)) {
                answer = i;
            }
        }

        System.out.println(answer);
    }
}

