    // We'll use a set of pairs (score, teamID) but to easily get max, we can store (-score, teamID)
    // Actually easier: maintain maxScore and a set of team IDs having that score.

    int maxScore = 0;
    set<int> bestTeams; // teams with score == maxScore
    // Initially all teams have score 0, so all teams are in bestTeams? But we don't know all team IDs upfront.
    // However, the problem says "contest starts with all teams having a score of 0" but we don't know all team IDs.
    // Actually we only know teams that appear in submissions. So initially, no team has been seen.
    // The TV shows the team with highest score, smallest ID. If no submissions yet, all scores 0,
    // but we don't know all teams. The problem implies we only consider teams that have appeared?
    // Actually typical interpretation: All teams exist from start with score 0, but we only know IDs that appear.
    // But the TV could show any team? Since all have score 0, the smallest ID among all teams? That's undefined.
    // In practice, we only care about times after first submission. So we'll handle it by noting that before any event,
    // there is no "current leader" that we need to track. We'll just start tracking from first event.

    // We'll store the current leader and the time it started being leader.
    int currentLeader = -1; // -1 means no leader yet (before first event)
    int leaderStartTime = 0;

    // total time each team is shown
    map<int, long long> totalTime;

    long long prevTime = 0;

    for (auto &[t, id, delta] : events) {
        // Update time for previous leader
        if (currentLeader != -1) {
            totalTime[currentLeader] += (t - prevTime);
        }

        // Update score
        score[id] += delta;
        int newScore = score[id];

        // Update maxScore and bestTeams
        if (newScore > maxScore) {
            maxScore = newScore;
            bestTeams.clear();
            bestTeams.insert(id);
        } else if (newScore == maxScore) {
            bestTeams.insert(id);
        } else {
            // If this team was previously in bestTeams, check if its score dropped below maxScore
            if (bestTeams.count(id)) {
                // Need to recalc: check if its current score is still maxScore
                // But we already know newScore < maxScore, so remove
                bestTeams.erase(id);
                // If bestTeams becomes empty, we need to find new maxScore
                if (bestTeams.empty()) {
                    // Recompute maxScore from all teams
                    maxScore = 0;
                    for (auto &p : score) {
                        if (p.second > maxScore) {
                            maxScore = p.second;
                        }
                    }
                    // Rebuild bestTeams
                    for (auto &p : score) {
                        if (p.second == maxScore) {
                            bestTeams.insert(p.first);
                        }
                    }
                }
            }
        }

        // Determine new leader
        if (bestTeams.empty()) {
            // No teams? Should not happen if there is at least one team.
            // But if no submissions yet, bestTeams empty.
            currentLeader = -1;
        } else {
            int newLeader = *bestTeams.begin(); // smallest ID among max score
            if (currentLeader != newLeader) {
                currentLeader = newLeader;
            }
        }

        prevTime = t;
    }

    // After last event, the leader continues until L
    if (currentLeader != -1) {
        totalTime[currentLeader] += (L - prevTime);
    }

    // Find team with max total time
    long long maxTime = -1;
    int answer = -1;
    for (auto &[id, time] : totalTime) {
        if (time > maxTime) {
            maxTime = time;
            answer = id;
        } else if (time == maxTime && id < answer) {
            answer = id;
        }
    }

    // If no team ever led (should not happen if N>=1), but just in case:
    if (answer == -1) {
        // Find smallest team ID that appeared? Problem guarantees at least one submission.
        answer = get<1>(events[0]);
    }

