int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    long long L;
    cin >> N >> M >> L;

    vector<Event> events(M);
    for (int i = 0; i < M; ++i) {
        cin >> events[i].t >> events[i].id >> events[i].delta;
    }

    sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        return a.t < b.t;
    });

    vector<long long> score(N + 1, 0);
    vector<long long> shown(N + 1, 0);

    // Set of ( -score, id ) so begin() is current leader:
    // highest score first, and for ties smallest id first.
    set<pair<long long, int>> ranking;
    for (int id = 1; id <= N; ++id) {
        ranking.insert({0, id});
    }

    long long prevTime = 0;
    int i = 0;

    while (i < M) {
        long long curTime = events[i].t;

        int leader = ranking.begin()->second;
        shown[leader] += curTime - prevTime;

        while (i < M && events[i].t == curTime) {
            int id = events[i].id;
            long long delta = events[i].delta;

            ranking.erase({-score[id], id});
            score[id] += delta;
            ranking.insert({-score[id], id});
            ++i;
        }

        prevTime = curTime;
    }

    int leader = ranking.begin()->second;
    shown[leader] += L - prevTime;

    int answer = 1;
    for (int id = 2; id <= N; ++id) {
        if (shown[id] > shown[answer] || (shown[id] == shown[answer] && id < answer)) {
            answer = id;
        }
    }

    cout << answer << '\n';
    return 0;
}
